import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintStream;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintStream ps = System.out;
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);
        int[] v = new int[10];
        String[] secondLine = br.readLine().split(" ");
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(secondLine[i]);
            v[x] = 1;
        }
        int[] ans = {1};
        int p = n / 2;
        while (p != 0) {
            if ((p & 1) == 1) {
                ans = multiplyPolynomial(ans, v, 998244353);
            }
            v = multiplyPolynomial(v, v, 998244353);
            p >>= 1;
        }
        long total = 0;
        for (int x : ans) {
            total += (long) x * x;
        }
        ps.println(total % 998244353);
    }

    static int[] multiplyPolynomial(int[] a, int[] b, int mod) {
        int size = 1;
        while (size < a.length + b.length - 1) size <<= 1;
        double[] A = new double[size];
        double[] B = new double[size];
        for (int i = 0; i < a.length; i++) {
            int val = (a[i] % mod + mod) % mod;
            A[i] = val & 0x7FFF;
        }
        for (int i = 0; i < b.length; i++) {
            int val = (b[i] % mod + mod) % mod;
            B[i] = val & 0x7FFF;
        }
        fftTransform(A, false);
        fftTransform(B, false);
        for (int i = 0; i < size; i++) {
            A[i] = A[i] * B[i];
        }
        fftTransform(A, true);
        int[] res = new int[a.length + b.length - 1];
        for (int i = 0; i < res.length; i++) {
            res[i] = (int) (Math.round(A[i]) % mod);
        }
        return res;
    }

    static void fftTransform(double[] a, boolean inv) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1) j -= bit;
            j += bit;
            if (i < j) {
                double temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            double angle = 2 * Math.PI / len * (inv ? -1 : 1);
            double wlenCos = Math.cos(angle);
            double wlenSin = Math.sin(angle);
            for (int i = 0; i < n; i += len) {
                double wRe = 1;
                double wIm = 0;
                for (int j = 0; j < len / 2; j++) {
                    int u = i + j;
                    int v = i + j + len / 2;
                    double uVal = a[u];
                    double vVal = a[v] * wRe - a[v] * wIm;
                    a[u] = uVal + vVal;
                    a[v] = uVal - vVal;
                    double nextWRe = wRe * wlenCos - wIm * wlenSin;
                    double nextWIm = wRe * wlenSin + wIm * wlenCos;
                    wRe = nextWRe;
                    wIm = nextWIm;
                }
            }
        }
        if (inv) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    }
}
